import React, { useEffect, useState } from "react";
import axios from "axios";

const API_URL = "http://localhost:4000/api";

function App() {
  const [amount, setAmount] = useState("");
  const [transactions, setTransactions] = useState([]);
  const [loading, setLoading] = useState(false);

  const fetchTransactions = async () => {
    const res = await axios.get(`${API_URL}/transactions`);
    setTransactions(res.data);
  };

  useEffect(() => {
    fetchTransactions();
  }, []);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    try {
      // NOTE: 'features' here needs to match your dataset's columns
      // (Time, V1...V28, Amount). This is placeholder/dummy data for demo.
      const dummyFeatures = { Time: 0, Amount: Number(amount) };

      await axios.post(`${API_URL}/transaction`, {
        transactionId: "TXN" + Date.now(),
        amount: Number(amount),
        features: dummyFeatures,
        senderPhone: "",
        senderEmail: "",
      });
      setAmount("");
      fetchTransactions();
    } catch (err) {
      console.error(err);
      alert("Error processing transaction. Check backend/ML service is running.");
    }
    setLoading(false);
  };

  return (
    <div className="container">
      <h1>🛡️ ChainShield</h1>
      <p>AI-Powered Blockchain-based Fraud Detection Dashboard</p>

      <div className="card">
        <h3>New Transaction</h3>
        <form onSubmit={handleSubmit}>
          <input
            type="number"
            placeholder="Amount (₹)"
            value={amount}
            onChange={(e) => setAmount(e.target.value)}
            required
          />
          <button type="submit" disabled={loading}>
            {loading ? "Processing..." : "Submit Transaction"}
          </button>
        </form>
      </div>

      <h3>Recent Transactions</h3>
      {transactions.map((t) => (
        <div key={t._id} className={`card ${t.status}`}>
          <strong>₹{t.amount}</strong> — {t.status.toUpperCase()}
          <div>Fraud Score: {(t.fraudScore * 100).toFixed(1)}%</div>
          {t.topReasons && t.topReasons.length > 0 && (
            <div>
              Top reasons:{" "}
              {t.topReasons.map((r) => `${r.feature} (${r.impact})`).join(", ")}
            </div>
          )}
          {t.blockchainTxHash && (
            <div style={{ fontSize: "12px", opacity: 0.7 }}>
              Blockchain Tx: {t.blockchainTxHash}
            </div>
          )}
        </div>
      ))}
    </div>
  );
}

export default App;
